index 27b7ec0..cefb4dd 100644
--- a/node/tag-normalizer/index.mjs
+++ b/node/tag-normalizer/index.mjs
@@ -1,3 +1,21 @@
 export function normalizeTags(tags) {
-  return tags;
+  if (!Array.isArray(tags)) {
+    throw new TypeError("tags must be an array");
+  }
+
+  const seen = new Set();
+  const result = [];
+
+  for (const tag of tags) {
+    const normalized = String(tag).trim().toLowerCase().replace(/ +/g, "-");
+    if (!/^[a-z0-9_-]+$/.test(normalized)) {
+      continue;
+    }
+    if (!seen.has(normalized)) {
+      seen.add(normalized);
+      result.push(normalized);
+    }
+  }
+
+  return result;
 }
